`,(0,n.jsxs)(r.li,{children:[(0,n.jsx)(r.strong,{children:(0,n.jsx)(r.a,{href:"https://support.claude.com/en/articles/14499648-how-scim-sync-works-for-enterprise-organizations",children:"How SCIM sync works for Enterprise organizations"})}),": how directory sync carries members and their group memberships into the organization."]}),`
